import json
import sys


def solve(request):
    initial = request.get("initial") or {}
    final = request.get("final") or {}
    txns = request.get("transactions") or []
    n = len(txns)

    # ------------------------------------------------------------------
    # Collect the universe of keys (state is tracked only over these).
    # ------------------------------------------------------------------
    keyset = set(initial) | set(final)
    for t in txns:
        for op in t.get("ops") or []:
            c = op[0]
            if c == "scan":
                for kv in op[3]:
                    keyset.add(kv[0])
            else:
                keyset.add(op[1])
    keys = sorted(keyset)
    nk = len(keys)
    kidx = {k: i for i, k in enumerate(keys)}

    # value -> bitmask bit; absent = None
    def bit(v):
        return 1 << (v + 9) if v is not None else (1 << 19)

    initial_vec = tuple(initial.get(k) for k in keys)
    final_vec = tuple(final.get(k) for k in keys)
    final_bits = tuple(bit(final.get(k)) for k in keys)

    # ------------------------------------------------------------------
    # Compile transactions.
    # ------------------------------------------------------------------
    ops_list = []
    pre = [0] * n                     # predecessor bitmask (real-time order)
    writes_any = [0] * n              # bitmask of keys written (ever)
    last_val = [dict() for _ in range(n)]   # key idx -> value of last write
    all_vals = [dict() for _ in range(n)]   # key idx -> bitset of all written values
    reqs = [dict() for _ in range(n)]       # key idx -> bitset of values that must be possible
    starts = [0] * n
    ends = [0] * n

    for i, t in enumerate(txns):
        starts[i] = t["start"]
        ends[i] = t["end"]
        ops = []
        for op in t["ops"]:
            c = op[0]
            if c == "get":
                ki = kidx[op[1]]
                ops.append(("g", ki, op[2]))
                reqs[i][ki] = reqs[i].get(ki, 0) | bit(op[2])
            elif c == "put":
                ki = kidx[op[1]]
                v = op[2]
                ops.append(("p", ki, v))
                writes_any[i] |= 1 << ki
                last_val[i][ki] = v
                all_vals[i][ki] = all_vals[i].get(ki, 0) | bit(v)
            elif c == "del":
                ki = kidx[op[1]]
                ops.append(("d", ki))
                writes_any[i] |= 1 << ki
                last_val[i][ki] = None
                all_vals[i][ki] = all_vals[i].get(ki, 0) | bit(None)
            elif c == "cas":
                _, key, old, new, want = op
                ki = kidx[key]
                want = bool(want)
                ops.append(("c", ki, old, new, want))
                reqs[i][ki] = reqs[i].get(ki, 0) | bit(old)
                # A valid execution of this transaction forces the CAS
                # outcome, so its write behaviour is unconditional.
                if want:
                    writes_any[i] |= 1 << ki
                    last_val[i][ki] = new
                    all_vals[i][ki] = all_vals[i].get(ki, 0) | bit(new)
            else:  # scan
                _, low, high, pairs = op
                rng = tuple(ki for ki in range(nk) if low <= keys[ki] < high)
                exp = []
                expmap = {}
                for kv in pairs:
                    ki = kidx[kv[0]]
                    exp.append((ki, kv[1]))
                    expmap[ki] = kv[1]
                ops.append(("s", rng, tuple(exp)))
                for ki in rng:
                    if ki in expmap:
                        reqs[i][ki] = reqs[i].get(ki, 0) | bit(expmap[ki])
                    else:
                        reqs[i][ki] = reqs[i].get(ki, 0) | bit(None)
        ops_list.append(tuple(ops))
        m = 0
        for j in range(n):
            if j != i and txns[j]["end"] <= t["start"]:
                m |= 1 << j
        pre[i] = m

    # ------------------------------------------------------------------
    # Per-subset precomputation.
    # ------------------------------------------------------------------
    full = (1 << n) - 1
    size = 1 << n
    rem_last_mask = [None] * size
    rem_all_mask = [None] * size
    rem_has = [None] * size
    norm_keys = [None] * size
    rem_reqs = [None] * size

    for mask in range(size):
        lm = [0] * nk
        am = [0] * nk
        has = [False] * nk
        reqlist = []
        for i in range(n):
            if (mask >> i) & 1:
                continue
            w = writes_any[i]
            if w:
                for ki in range(nk):
                    if (w >> ki) & 1:
                        has[ki] = True
                        lm[ki] |= bit(last_val[i][ki])
                        am[ki] |= all_vals[i].get(ki, 0)
            rq = reqs[i]
            if rq:
                for ki, r in rq.items():
                    reqlist.append((ki, r))
        rem_last_mask[mask] = lm
        rem_all_mask[mask] = am
        rem_has[mask] = has
        norm_keys[mask] = tuple(ki for ki in range(nk) if has[ki])
        rem_reqs[mask] = tuple(reqlist)

    failed = set()

    # ------------------------------------------------------------------
    # Execute one transaction atomically from vec.
    # ------------------------------------------------------------------
    def apply(i, vec):
        st = list(vec)
        for op in ops_list[i]:
            c = op[0]
            if c == "g":
                if st[op[1]] != op[2]:
                    return None
            elif c == "p":
                st[op[1]] = op[2]
            elif c == "d":
                st[op[1]] = None
            elif c == "c":
                _, ki, old, new, want = op
                ok = st[ki] == old
                if ok != want:
                    return None
                if ok:
                    st[ki] = new
            else:
                _, rng, exp = op
                ne = len(exp)
                j = 0
                for ki in rng:
                    v = st[ki]
                    if v is not None:
                        if j >= ne or exp[j][0] != ki or exp[j][1] != v:
                            return None
                        j += 1
                if j != ne:
                    return None
        return tuple(st)

    # ------------------------------------------------------------------
    # Necessary-condition pruning.
    # ------------------------------------------------------------------
    def feasible(mask, vec):
        lm = rem_last_mask[mask]
        has = rem_has[mask]
        am = rem_all_mask[mask]
        for ki in range(nk):
            if has[ki]:
                if not (final_bits[ki] & lm[ki]):
                    return False
            elif vec[ki] != final_vec[ki]:
                return False
        for ki, rq in rem_reqs[mask]:
            if not (rq & (bit(vec[ki]) | am[ki])):
                return False
        return True

    def dfs(mask, vec):
        if mask == full:
            return () if vec == final_vec else None
        nk_list = norm_keys[mask]
        mkey = (mask, tuple(vec[ki] for ki in nk_list))
        if mkey in failed:
            return None
        if not feasible(mask, vec):
            failed.add(mkey)
            return None
        notmask = full ^ mask
        cands = []
        for i in range(n):
            if not (mask >> i) & 1 and (pre[i] & notmask) == 0:
                cands.append(i)
        cands.sort(key=lambda i: (ends[i], starts[i], i))
        for i in cands:
            ns = apply(i, vec)
            if ns is None:
                continue
            res = dfs(mask | (1 << i), ns)
            if res is not None:
                return (i,) + res
        failed.add(mkey)
        return None

    res = dfs(0, initial_vec)
    if res is None:
        return {"order": None}
    return {"order": [txns[i]["id"] for i in res]}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        out.write(json.dumps(solve(req)))
        out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
