import itertools, json, random, sys
sys.path.insert(0, '/app')
from main import solve
from public_contract import valid_history


def simulate(req, order):
    tx = {t['id']: t for t in req['transactions']}
    d = dict(req['initial'])
    for name in order:
        for op in tx[name]['ops']:
            if op[0] == 'get':
                if d.get(op[1]) != op[2]: return False
            elif op[0] == 'put':
                d[op[1]] = op[2]
            elif op[0] == 'del':
                d.pop(op[1], None)
            elif op[0] == 'cas':
                _, key, old, new, want = op
                ok = d.get(key) == old
                if ok is not want: return False
                if ok:
                    if new is None: d.pop(key, None)
                    else: d[key] = new
            else:
                if sorted([[k, v] for k, v in d.items() if op[1] <= k < op[2]]) != op[3]:
                    return False
    return d == req['final']


def brute(req):
    ids = [t['id'] for t in req['transactions']]
    tx = {t['id']: t for t in req['transactions']}
    for perm in itertools.permutations(ids):
        ranks = {x: i for i, x in enumerate(perm)}
        ok = True
        for a in ids:
            for b in ids:
                if tx[a]['end'] <= tx[b]['start'] and ranks[a] >= ranks[b]:
                    ok = False; break
            if not ok: break
        if ok and simulate(req, perm):
            return True
    return False


def gen_sat(rng, maxn=6, maxkeys=3, maxops=4):
    n = rng.randint(0, maxn)
    keys = sorted(rng.sample(['a', 'b', 'c', 'd', 'e', 'f'], rng.randint(0, maxkeys)))
    times = []
    for _ in range(n):
        s = rng.randint(0, 6)
        e = s + rng.randint(1, 4)
        times.append((s, e))
    # random topological order respecting real-time
    remaining = list(range(n))
    order = []
    while remaining:
        ready = [i for i in remaining if all(not (times[j][1] <= times[i][0]) for j in remaining if j != i)]
        i = rng.choice(ready)
        order.append(i); remaining.remove(i)
    state = {}
    txns = []
    for pos, i in enumerate(order):
        s, e = times[i]
        ops = []
        for _ in range(rng.randint(1, maxops)):
            c = rng.choice(['get', 'put', 'del', 'cas', 'scan'])
            if not keys:
                c = 'put'
            k = rng.choice(keys) if keys else 'a'
            if c == 'get':
                ops.append(['get', k, state.get(k)])
            elif c == 'put':
                v = rng.randint(-2, 2)
                ops.append(['put', k, v]); state[k] = v
            elif c == 'del':
                ops.append(['del', k]); state.pop(k, None)
            elif c == 'cas':
                old = state.get(k)
                if rng.random() < 0.6:
                    want = True
                    new = rng.choice([None] + list(range(-2, 3)))
                else:
                    want = False
                    new = rng.randint(-2, 2)
                    # make condition likely false
                    while state.get(k) == old and rng.random() < 0.9:
                        old = rng.choice([None, -2, -1, 0, 1, 2, 99])
                ops.append(['cas', k, old, new, want])
                if want:
                    if new is None: state.pop(k, None)
                    else: state[k] = new
            else:
                lo = rng.choice(keys)
                hi = rng.choice(keys + ['z'])
                if lo >= hi: lo, hi = hi, lo
                if lo == hi: hi = chr(ord(hi) + 1)
                pairs = sorted([[kk, vv] for kk, vv in state.items() if lo <= kk < hi])
                ops.append(['scan', lo, hi, pairs])
        txns.append({'id': 't%d' % i, 'start': s, 'end': e, 'ops': ops})
    txns.sort(key=lambda t: t['id'])
    return {'initial': {}, 'final': dict(state), 'transactions': txns}


def mutate(rng, req):
    r = json.loads(json.dumps(req))
    if r['transactions'] and rng.random() < 0.7:
        t = rng.choice(r['transactions'])
        op = rng.choice(t['ops'])
        if op[0] == 'get':
            op[2] = rng.choice([None, -3, -2, -1, 0, 1, 2, 3])
        elif op[0] == 'cas':
            if rng.random() < 0.5:
                op[2] = rng.choice([None, -3, 3])
            else:
                op[4] = not op[4]
        elif op[0] == 'scan':
            op[3] = [] if op[3] else [['a', 7]]
        else:
            op[2] = rng.choice([-3, 3])
    else:
        k = rng.choice(['a', 'b', 'c', 'zz'])
        if k in r['final']:
            del r['final'][k]
        else:
            r['final'][k] = rng.choice([-3, 0, 3])
    return r


def main():
    rng = random.Random(12345)
    trials = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
    bad = 0
    for it in range(trials):
        req = gen_sat(rng)
        if rng.random() < 0.5:
            req = mutate(rng, req)
        expect = brute(req)
        got = solve(req)
        if expect:
            if got['order'] is None or not valid_history(req, got['order']):
                print('FAIL sat', it, json.dumps(req)); bad += 1
        else:
            if got['order'] is not None:
                print('FAIL unsat', it, json.dumps(req), got); bad += 1
        if bad > 5: break
    print('done', trials, 'bad', bad)

if __name__ == '__main__':
    main()
