import test_diff as td

def apply_naive(t, d):
    d = dict(d)
    for op in t['ops']:
        if op[0]=='get':
            if d.get(op[1])!=op[2]: return None
        elif op[0]=='put': d[op[1]]=op[2]
        elif op[0]=='del': d.pop(op[1],None)
        elif op[0]=='cas':
            _,k,old,new,want=op; ok=d.get(k)==old
            if ok is not want: return None
            if ok:
                if new is None: d.pop(k,None)
                else: d[k]=new
        else:
            if sorted([[k,v] for k,v in d.items() if op[1]<=k<op[2]])!=op[3]: return None
    return d

def dp_solve(req):
    tx=req['transactions']; n=len(tx)
    pre=[0]*n
    for i in range(n):
        for j in range(n):
            if j!=i and tx[j]['end']<=tx[i]['start']: pre[i]|=1<<j
    full=(1<<n)-1
    init=tuple(sorted(req['initial'].items()))
    dp=[set() for _ in range(1<<n)]
    dp[0].add(init)
    for mask in range(1<<n):
        if not dp[mask]: continue
        for i in range(n):
            if (mask>>i)&1 or (pre[i]&~mask): continue
            nm=mask|1<<i
            for st in dp[mask]:
                nd=apply_naive(tx[i],dict(st))
                if nd is not None: dp[nm].add(tuple(sorted(nd.items())))
    return tuple(sorted(req['final'].items())) in dp[full]

